// Applies the accent colour to every button on the main screen.
static void apply_button_color(lv_color_t c)
{
    lv_obj_t * buttons[] = { ui_ColorSave,ui_Button1, ui_Button2, ui_Button3, ui_Button4, ui_Button5, ui_ButtonIP, ui_ButtonColor, ui_ButtonUnits };
    for(size_t i = 0; i < sizeof(buttons) / sizeof(buttons[0]); i++) {
        lv_obj_set_style_bg_color(buttons[i], c, LV_STATE_DEFAULT);
    }
}

// Takes the wheel's current colour (hue/saturation from the wheel, brightness
// from the slider) as the new button colour.
static void update_color_from_wheel(lv_obj_t * wheel)
{
    lv_color_t c = lv_colorwheel_get_rgb(wheel);
    color = lv_color_to32(c) & 0xFFFFFF;
    apply_button_color(c);
}

static void color_wheel_event(lv_event_t * e)
{
    update_color_from_wheel(lv_event_get_target(e));
}

static void brightness_slider_event(lv_event_t * e)
{
    lv_obj_t * wheel = lv_event_get_user_data(e);
    lv_color_hsv_t hsv = lv_colorwheel_get_hsv(wheel);
    hsv.v = lv_slider_get_value(lv_event_get_target(e));
    lv_colorwheel_set_hsv(wheel, hsv);
    update_color_from_wheel(wheel);
}

static bool nvs_read_u32(const char * key, uint32_t * out)
{
    nvs_handle_t handle;
    if(nvs_open(UI_NVS_NAMESPACE, NVS_READONLY, &handle) != ESP_OK) return false;
    bool found = nvs_get_u32(handle, key, out) == ESP_OK;
    nvs_close(handle);
    return found;
}

static void nvs_write_u32(const char * key, uint32_t value)
{
    nvs_handle_t handle;
    if(nvs_open(UI_NVS_NAMESPACE, NVS_READWRITE, &handle) != ESP_OK) return;
    nvs_set_u32(handle, key, value);
    nvs_commit(handle);
    nvs_close(handle);
}

// Loads the saved UI preferences from NVS; keeps the defaults if none are stored.
// Defined with the power page below.
static void load_power_percent(void);

void ui_load_preferences(void)
{
    uint32_t saved;
    if(nvs_read_u32(UI_NVS_COLOR_KEY, &saved)) color = saved;
    if(nvs_read_u32(UI_NVS_DECIMALS_KEY, &saved)) showDecimals = saved != 0;
    if(nvs_read_u32(UI_NVS_FAHRENHEIT_KEY, &saved)) useFahrenheit = saved != 0;
    load_power_percent();
}

bool ui_show_decimals(void)
{
    return showDecimals;
}

bool ui_use_fahrenheit(void)
{
    return useFahrenheit;
}

static void toggle_units(void)
{
    useFahrenheit = !useFahrenheit;
    lv_label_set_text(ui_LabelUnits, useFahrenheit ? "°F" : "°C");
    nvs_write_u32(UI_NVS_FAHRENHEIT_KEY, useFahrenheit);
}

// Short click toggles Celsius/Fahrenheit, long press toggles decimals.
// SHORT_CLICKED (not CLICKED) so a long press does not also switch units.
static void units_button_event(lv_event_t * e)
{
    lv_event_code_t code = lv_event_get_code(e);
    if(code == LV_EVENT_SHORT_CLICKED) {
        toggle_units();
    }
    else if(code == LV_EVENT_LONG_PRESSED) {
        showDecimals = !showDecimals;
        nvs_write_u32(UI_NVS_DECIMALS_KEY, showDecimals);
    }
}
// Colour requested from another task (the web server); applied by
// pending_settings_timer in the LVGL context, since LVGL is not thread safe.
static volatile bool colorPending = false;
static volatile uint32_t pendingColor;

void ui_set_button_color(uint32_t rgb)
{
    pendingColor = rgb & 0xFFFFFF;
    colorPending = true;
}

uint32_t ui_get_button_color(void)
{
    return color;
}

// Unit/decimals requested from another task: -1 = nothing pending, else 0/1.
static volatile int8_t pendingFahrenheit = -1;
static volatile int8_t pendingDecimals = -1;

void ui_set_use_fahrenheit(bool enabled)
{
    pendingFahrenheit = enabled ? 1 : 0;
}

void ui_set_show_decimals(bool enabled)
{
    pendingDecimals = enabled ? 1 : 0;
}

// Applies settings queued by other tasks, in the LVGL context.
static void pending_settings_timer(lv_timer_t * timer)
{
    if(colorPending) {
        colorPending = false;
        color = pendingColor;
        apply_button_color(lv_color_hex(color));
        nvs_write_u32(UI_NVS_COLOR_KEY, color);
    }
    if(pendingFahrenheit >= 0) {
        useFahrenheit = pendingFahrenheit == 1;
        pendingFahrenheit = -1;
        lv_label_set_text(ui_LabelUnits, useFahrenheit ? "°F" : "°C");
        nvs_write_u32(UI_NVS_FAHRENHEIT_KEY, useFahrenheit);
    }
    if(pendingDecimals >= 0) {
        showDecimals = pendingDecimals == 1;
        pendingDecimals = -1;
        nvs_write_u32(UI_NVS_DECIMALS_KEY, showDecimals);
    }
}

// Hides the panel instead of deleting it: the Save button lives inside the
// panel, and freeing it while LVGL is still dispatching its event crashes.
static void color_close_event(lv_event_t * e)
{
    if(lv_event_get_code(e) != LV_EVENT_CLICKED) return;
    beep();
    nvs_write_u32(UI_NVS_COLOR_KEY, color);
    lv_obj_set_style_bg_color(e->current_target, lv_color_hex(color), LV_STATE_DEFAULT);
    lv_obj_add_flag(ui_ColorPanel, LV_OBJ_FLAG_HIDDEN);
    lv_obj_add_flag(ui_ColorBackdrop, LV_OBJ_FLAG_HIDDEN);
}

// Tap outside the panel: discard the previewed colour and close.
static void color_cancel_event(lv_event_t * e)
{
    if(lv_event_get_code(e) != LV_EVENT_CLICKED) return;
    color = colorBeforeEdit;
    apply_button_color(lv_color_hex(color));
    lv_obj_add_flag(ui_ColorPanel, LV_OBJ_FLAG_HIDDEN);
    lv_obj_add_flag(ui_ColorBackdrop, LV_OBJ_FLAG_HIDDEN);
}

// Builds the colour panel once, hidden; it is shown/hidden from then on.
static void create_color_panel(void)
{
    // Created first so it sits below the panel; slightly dims the screen.
    ui_ColorBackdrop = lv_obj_create(ui_Screen1);
    lv_obj_set_size(ui_ColorBackdrop, LV_PCT(100), LV_PCT(100));
    lv_obj_center(ui_ColorBackdrop);
    lv_obj_set_style_radius(ui_ColorBackdrop, 0, LV_PART_MAIN);
    lv_obj_set_style_border_width(ui_ColorBackdrop, 0, LV_PART_MAIN);
    lv_obj_set_style_bg_color(ui_ColorBackdrop, lv_color_black(), LV_PART_MAIN);
    lv_obj_set_style_bg_opa(ui_ColorBackdrop, LV_OPA_40, LV_PART_MAIN);
    lv_obj_clear_flag(ui_ColorBackdrop, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_add_flag(ui_ColorBackdrop, LV_OBJ_FLAG_HIDDEN);
    lv_obj_add_event_cb(ui_ColorBackdrop, color_cancel_event, LV_EVENT_CLICKED, NULL);

    ui_ColorPanel = lv_obj_create(ui_Screen1);
    lv_obj_set_size(ui_ColorPanel, 260, 300);
    lv_obj_center(ui_ColorPanel);
    lv_obj_clear_flag(ui_ColorPanel, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_add_flag(ui_ColorPanel, LV_OBJ_FLAG_HIDDEN);

    ui_ColorWheel = lv_colorwheel_create(ui_ColorPanel, true);
    lv_obj_set_size(ui_ColorWheel, 170, 170);
    lv_obj_align(ui_ColorWheel, LV_ALIGN_TOP_MID, 0, 0);
    // Brightness has its own slider, so keep the wheel on hue only.
    lv_colorwheel_set_mode_fixed(ui_ColorWheel, true);
    lv_obj_add_event_cb(ui_ColorWheel, color_wheel_event, LV_EVENT_VALUE_CHANGED, NULL);

    ui_BrightnessSlider = lv_slider_create(ui_ColorPanel);
    lv_obj_set_width(ui_BrightnessSlider, 200);
    lv_obj_align(ui_BrightnessSlider, LV_ALIGN_TOP_MID, 0, 190);
    lv_obj_set_style_bg_color(ui_BrightnessSlider, lv_color_hex(color), LV_STATE_DEFAULT);

    // Lower bound keeps the buttons from turning fully black.
    lv_slider_set_range(ui_BrightnessSlider, 10, 100);
    lv_obj_add_event_cb(ui_BrightnessSlider, brightness_slider_event, LV_EVENT_VALUE_CHANGED, ui_ColorWheel);

    ui_ColorSave = lv_btn_create(ui_ColorPanel);
    lv_obj_set_size(ui_ColorSave, 100, 40);
    lv_obj_align(ui_ColorSave, LV_ALIGN_BOTTOM_MID, 0, 0);
    lv_obj_set_style_bg_color(ui_ColorSave, lv_color_hex(color), LV_STATE_DEFAULT);
    lv_obj_add_event_cb(ui_ColorSave, color_close_event, LV_EVENT_CLICKED, NULL);

    lv_obj_t * label = lv_label_create(ui_ColorSave);
    lv_label_set_text(label, "Save");
    lv_obj_set_style_text_font(label, &lv_font_montserrat_18, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_center(label);
}

// Colour button: tap opens the colour panel, long press checks for a
// firmware update (OTA). SHORT_CLICKED so a long press does not also open
// the panel.
static void color_open_event(lv_event_t * e)
{
    lv_event_code_t code = lv_event_get_code(e);
    if(code == LV_EVENT_LONG_PRESSED) {
        beepDouble();
        otaStartCheck();
        return;
    }
    if(code != LV_EVENT_SHORT_CLICKED) return;
    beep();
    // Sync the controls with the current colour, then show the panel on top.
    lv_colorwheel_set_rgb(ui_ColorWheel, lv_color_hex(color));
    lv_slider_set_value(ui_BrightnessSlider, lv_colorwheel_get_hsv(ui_ColorWheel).v, LV_ANIM_OFF);
    colorBeforeEdit = color;
    // Backdrop over the screen, panel over the backdrop.
    lv_obj_move_foreground(ui_ColorBackdrop);
    lv_obj_move_foreground(ui_ColorPanel);
    lv_obj_clear_flag(ui_ColorBackdrop, LV_OBJ_FLAG_HIDDEN);
    lv_obj_clear_flag(ui_ColorPanel, LV_OBJ_FLAG_HIDDEN);
}

// ---- Power page ------------------------------------------------------------
// Swiping left/right on the main screen slides to a second page that looks
// the same, but the target label shows a power percentage (50-100%) that +/-
// change. Instead of duplicating every widget, they are moved onto the other
// screen object as it slides in, so all labels keep updating unchanged.
#define POWER_PERCENT_MIN 50
#define POWER_PERCENT_MAX 100
#define PAGE_SLIDE_MS     300

static lv_obj_t * ui_ScreenPower;
static volatile bool powerPage = false;
static volatile int powerPercent = POWER_PERCENT_MAX;

bool ui_power_page(void)
{
    return powerPage;
}

int ui_get_power_percent(void)
{
    return powerPercent;
}

// Restores the saved percentage (kept within POWER_PERCENT_MIN..MAX).
static void load_power_percent(void)
{
    uint32_t saved;
    if(nvs_read_u32(UI_NVS_POWER_KEY, &saved) &&
       saved >= POWER_PERCENT_MIN && saved <= POWER_PERCENT_MAX) {
        powerPercent = (int)saved;
    }
}

void ui_save_power_percent(void)
{
    nvs_write_u32(UI_NVS_POWER_KEY, (uint32_t)powerPercent);
}

void ui_adjust_power_percent(int delta)
{
    int value = powerPercent + delta;
    if(value < POWER_PERCENT_MIN) value = POWER_PERCENT_MIN;
    if(value > POWER_PERCENT_MAX) value = POWER_PERCENT_MAX;
    powerPercent = value;
}

static void switch_page(lv_scr_load_anim_t anim)
{
    lv_obj_t * from = lv_scr_act();
    lv_obj_t * to = (from == ui_Screen1) ? ui_ScreenPower : ui_Screen1;
    // Moving child 0 each time keeps the original stacking order.
    while(lv_obj_get_child_cnt(from) > 0) {
        lv_obj_set_parent(lv_obj_get_child(from, 0), to);
    }
    powerPage = (to == ui_ScreenPower);
    // Switching pages stops the moka, like pressing OFF, so a PID brew or a
    // manual power run never continues on the other page.
    mokaSwitchOff(NULL);
    // No PREHEAT on the power page.
    if(powerPage) lv_obj_add_flag(ui_Button2, LV_OBJ_FLAG_HIDDEN);
    else lv_obj_clear_flag(ui_Button2, LV_OBJ_FLAG_HIDDEN);
    lv_scr_load_anim(to, anim, PAGE_SLIDE_MS, 0, false);
}

// ---- OTA popup ---------------------------------------------------------------
// Modal window showing the progress of a firmware update (started with a long
// press on the colour button). The update runs in its own task; this only
// reads its status from an LVGL timer, so LVGL is only touched here.
#define OTA_POPUP_REFRESH_MS 200

static lv_obj_t * ui_OtaBackdrop;
static lv_obj_t * ui_OtaPopup;
static lv_obj_t * ui_OtaStatusLabel;
static lv_obj_t * ui_OtaVersionLabel;
static lv_obj_t * ui_OtaConfirmButton;
static lv_obj_t * ui_OtaConfirmLabel;
static lv_obj_t * ui_OtaCancelButton;

static void ota_confirm_event(lv_event_t * e)
{
    if(lv_event_get_code(e) != LV_EVENT_CLICKED) return;
    beep();
    otaConfirm();
}

static void ota_cancel_event(lv_event_t * e)
{
    if(lv_event_get_code(e) != LV_EVENT_CLICKED) return;
    beep();
    otaCancel();
}

static lv_obj_t * create_ota_button(const char * text, lv_event_cb_t cb)
{
    lv_obj_t * button = lv_btn_create(ui_OtaPopup);
    lv_obj_set_size(button, 110, 40);
    lv_obj_set_style_bg_color(button, lv_color_hex(color), LV_STATE_DEFAULT);
    lv_obj_add_event_cb(button, cb, LV_EVENT_CLICKED, NULL);
    lv_obj_t * label = lv_label_create(button);
    lv_label_set_text(label, text);
    lv_obj_set_style_text_font(label, &lv_font_montserrat_18, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_center(label);
    if(cb == ota_confirm_event) ui_OtaConfirmLabel = label;
    return button;
}
static lv_obj_t * ui_OtaBar;

static void create_ota_popup(void)
{
    // Blocks touches on the screen while the update runs.
    ui_OtaBackdrop = lv_obj_create(ui_Screen1);
    lv_obj_set_size(ui_OtaBackdrop, LV_PCT(100), LV_PCT(100));
    lv_obj_center(ui_OtaBackdrop);
    lv_obj_set_style_radius(ui_OtaBackdrop, 0, LV_PART_MAIN);
    lv_obj_set_style_border_width(ui_OtaBackdrop, 0, LV_PART_MAIN);
    lv_obj_set_style_bg_color(ui_OtaBackdrop, lv_color_black(), LV_PART_MAIN);
    lv_obj_set_style_bg_opa(ui_OtaBackdrop, LV_OPA_50, LV_PART_MAIN);
    lv_obj_clear_flag(ui_OtaBackdrop, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_add_flag(ui_OtaBackdrop, LV_OBJ_FLAG_HIDDEN);

    ui_OtaPopup = lv_obj_create(ui_Screen1);
    lv_obj_set_size(ui_OtaPopup, 300, 250);
    lv_obj_center(ui_OtaPopup);
    lv_obj_clear_flag(ui_OtaPopup, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_add_flag(ui_OtaPopup, LV_OBJ_FLAG_HIDDEN);

    lv_obj_t * title = lv_label_create(ui_OtaPopup);
    lv_label_set_text(title, "Firmware update");
    lv_obj_set_style_text_font(title, &lv_font_montserrat_18, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_align(title, LV_ALIGN_TOP_MID, 0, 0);

    // "Installed: x / Available: y"
    ui_OtaVersionLabel = lv_label_create(ui_OtaPopup);
    lv_label_set_text(ui_OtaVersionLabel, "");
    lv_obj_set_style_text_font(ui_OtaVersionLabel, &lv_font_montserrat_18, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_text_align(ui_OtaVersionLabel, LV_TEXT_ALIGN_CENTER, LV_PART_MAIN);
    lv_obj_align(ui_OtaVersionLabel, LV_ALIGN_TOP_MID, 0, 30);

    ui_OtaStatusLabel = lv_label_create(ui_OtaPopup);
    lv_label_set_text(ui_OtaStatusLabel, "");
    lv_obj_set_style_text_font(ui_OtaStatusLabel, &lv_font_montserrat_18, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_align(ui_OtaStatusLabel, LV_ALIGN_TOP_MID, 0, 90);

    ui_OtaBar = lv_bar_create(ui_OtaPopup);
    lv_obj_set_size(ui_OtaBar, 240, 16);
    lv_obj_align(ui_OtaBar, LV_ALIGN_TOP_MID, 0, 125);
    lv_bar_set_range(ui_OtaBar, 0, 100);
    lv_obj_add_flag(ui_OtaBar, LV_OBJ_FLAG_HIDDEN);

    // Update / Reinstall: only while an install waits for confirmation.
    // Cancel: always.
    ui_OtaConfirmButton = create_ota_button("Update", ota_confirm_event);
    lv_obj_align(ui_OtaConfirmButton, LV_ALIGN_BOTTOM_LEFT, 0, 0);
    lv_obj_add_flag(ui_OtaConfirmButton, LV_OBJ_FLAG_HIDDEN);
    ui_OtaCancelButton = create_ota_button("Cancel", ota_cancel_event);
    lv_obj_align(ui_OtaCancelButton, LV_ALIGN_BOTTOM_MID, 0, 0);
}

static void ota_popup_timer(lv_timer_t * timer)
{
    static char shownStatus[40] = "";
    bool popupHidden = lv_obj_has_flag(ui_OtaPopup, LV_OBJ_FLAG_HIDDEN);

    if(!otaInProgress()) {
        if(!popupHidden) {
            lv_obj_add_flag(ui_OtaPopup, LV_OBJ_FLAG_HIDDEN);
            lv_obj_add_flag(ui_OtaBackdrop, LV_OBJ_FLAG_HIDDEN);
            shownStatus[0] = '\0';
        }
        return;
    }

    if(popupHidden) {
        lv_obj_move_foreground(ui_OtaBackdrop);
        lv_obj_move_foreground(ui_OtaPopup);
        lv_obj_clear_flag(ui_OtaBackdrop, LV_OBJ_FLAG_HIDDEN);
        lv_obj_clear_flag(ui_OtaPopup, LV_OBJ_FLAG_HIDDEN);
    }

    // Status without the "OTA: " prefix used on the IP label.
    const char * status = otaStatusText();
    if(strncmp(status, "OTA: ", 5) == 0) status += 5;
    if(strcmp(status, shownStatus) != 0) {
        strncpy(shownStatus, status, sizeof(shownStatus) - 1);
        shownStatus[sizeof(shownStatus) - 1] = '\0';
        lv_label_set_text(ui_OtaStatusLabel, shownStatus);
    }

    // Versions: the available one is known once the check has run.
    static char shownVersions[64] = "";
    const char * available = otaAvailableVersion();
    char versions[64];
    snprintf(versions, sizeof(versions), "Installed: %s\nAvailable: %s",
             otaInstalledVersion(), available[0] ? available : "checking...");
    if(strcmp(versions, shownVersions) != 0) {
        strcpy(shownVersions, versions);
        lv_label_set_text(ui_OtaVersionLabel, shownVersions);
        lv_obj_align(ui_OtaVersionLabel, LV_ALIGN_TOP_MID, 0, 30);
    }

    // Update next to Cancel while waiting for confirmation, Cancel alone
    // otherwise.
    bool awaiting = otaAwaitingConfirm();
    if(awaiting == lv_obj_has_flag(ui_OtaConfirmButton, LV_OBJ_FLAG_HIDDEN)) {
        if(awaiting) {
            lv_label_set_text(ui_OtaConfirmLabel, otaConfirmIsReinstall() ? "Reinstall" : "Update");
            lv_obj_clear_flag(ui_OtaConfirmButton, LV_OBJ_FLAG_HIDDEN);
            lv_obj_align(ui_OtaCancelButton, LV_ALIGN_BOTTOM_RIGHT, 0, 0);
        }
        else {
            lv_obj_add_flag(ui_OtaConfirmButton, LV_OBJ_FLAG_HIDDEN);
            lv_obj_align(ui_OtaCancelButton, LV_ALIGN_BOTTOM_MID, 0, 0);
        }
    }

    int percent = otaProgress();
    if(percent >= 0) {
        lv_bar_set_value(ui_OtaBar, percent, LV_ANIM_OFF);
        lv_obj_clear_flag(ui_OtaBar, LV_OBJ_FLAG_HIDDEN);
    }
    else {
        lv_obj_add_flag(ui_OtaBar, LV_OBJ_FLAG_HIDDEN);
    }
}

static void screen_gesture_event(lv_event_t * e)
{
    if(lv_event_get_code(e) != LV_EVENT_GESTURE) return;
    // Ignore while a slide is running (the target screen is not active yet)
    // and while the colour panel is open (its slider/wheel are dragged).
    if(lv_event_get_current_target(e) != lv_scr_act()) return;
    if(!lv_obj_has_flag(ui_ColorPanel, LV_OBJ_FLAG_HIDDEN)) return;
    // No page switching while a firmware update is shown.
    if(otaInProgress()) return;

    lv_dir_t dir = lv_indev_get_gesture_dir(lv_indev_get_act());
    if(dir == LV_DIR_LEFT) switch_page(LV_SCR_LOAD_ANIM_MOVE_LEFT);
    else if(dir == LV_DIR_RIGHT) switch_page(LV_SCR_LOAD_ANIM_MOVE_RIGHT);
    else return;
    // The swipe must not also count as a click on the button it started on.
    lv_indev_wait_release(lv_indev_get_act());
}

